var _theme = { name: "blue" };
// Copies the live side of the current palette onto T: light values first, then
// the `dark:` overrides when T.isDark. Called by BOTH applyTheme and
// applyDarkMode so the two can be invoked in any order and the result is the
// same - which matters because App re-applies dark mode on every render.
function paintPalette() {
  var p = THEMES[_theme.name] || THEMES.blue;
  for (var k in p) { if (k !== "dark") T[k] = p[k]; }
  if (T.isDark && p.dark) { for (var d in p.dark) { T[d] = p.dark[d]; } }
  var sem = T.isDark ? SEMANTIC_DARK : SEMANTIC_LIGHT;
  for (var s in sem) { T[s] = sem[s]; }
  T.heroInk = T.heroText;
  // The one token the motion stylesheet needs at runtime: keyframes can't read
  // the mutated T object, so the row-flash tint is published as a CSS variable
  // and re-published whenever the palette changes.
  if (typeof document !== "undefined") document.documentElement.style.setProperty("--m-flash", T.orangeDim);
}
function applyTheme(name) {
  _theme.name = THEMES[name] ? name : "blue";
  paintPalette();
}
applyTheme("blue");

// Display names for each theme id, keyed the same as THEMES. Single source of
// truth for the label shown in Profile / Privacy rows and the Appearance picker.
var THEME_LABELS = { purple: "Mika's Violet", classic: "Dark Ember", blue: "Cornflower Ocean" };
function themeLabelOf(name) { return THEME_LABELS[name] || THEME_LABELS.purple; }
// Swatch pair for the Appearance picker, taken from the side of the palette
// that is actually live - so the preview chip never advertises a light hero
// while the app is sitting in dark mode.
function themeSwatch(name, dark) {
  var p = THEMES[name] || THEMES.blue;
  var side = (dark && p.dark) ? p.dark : p;
  return { a: side.swatchA || p.swatchA, b: side.swatchB || p.swatchB };
}

// The sign-up journey and the wizards built on it do not use the app chrome's
// surfaces. They sit on their own ground - a warm gradient with its own inks,
// panels and hairlines - so that the whole flow reads as one continuous piece
// rather than a series of app screens. That ground is a full palette in its own
// right, and like T it now comes in a light and a dark side.
//
// Dark keeps the warmth rather than reusing T's neutrals: the journey stays
// recognisably itself, just lit from the other direction.
var JOURNEY_LIGHT = {
  bg: "linear-gradient(160deg,#FDF5EC 0%,#FAF0E4 40%,#F5E8D8 100%)",
  shaderBase: "#FBF3E8",
  ink: "#1A1410", ink2: "#6B5C4E", ink3: "#B0A396",
  // Body ink for copy sitting directly on JrShaderBg. ink2 measures 5.8:1 on
  // the plain ground but collapses once a ribbon core passes under it, so this
  // pushes further from the ribbon: deeper on light, brighter on dark.
  ink2sh: "#4A3D33",
  card: "#FFFFFF",
  panel: "rgba(255,255,255,0.85)",
  fill0: "rgba(0,0,0,0.03)", fill1: "rgba(0,0,0,0.05)",
  fill2: "rgba(0,0,0,0.07)", fill3: "rgba(0,0,0,0.09)",
  line: "rgba(0,0,0,0.08)", line2: "rgba(0,0,0,0.13)",
};
var JOURNEY_DARK = {
  bg: "linear-gradient(160deg,#231D17 0%,#1B1712 40%,#141110 100%)",
  shaderBase: "#1A1610",
  ink: "#F5EFE7", ink2: "#BCAC9A", ink3: "#83725F",
  ink2sh: "#EFE5D8",
  card: "#262019",
  panel: "rgba(255,255,255,0.07)",
  fill0: "rgba(255,255,255,0.035)", fill1: "rgba(255,255,255,0.06)",
  fill2: "rgba(255,255,255,0.09)", fill3: "rgba(255,255,255,0.13)",
  line: "rgba(255,255,255,0.12)", line2: "rgba(255,255,255,0.18)",
};
// Mutated in place like T, and read at render time by every journey screen.
var J = {};
function paintJourney() {
  var side = T.isDark ? JOURNEY_DARK : JOURNEY_LIGHT;
  for (var k in side) { J[k] = side[k]; }
}

var LIGHT_BG = "#F7F3EE";
var LIGHT_CARD = "#FFFFFF";
var DARK_BG = "#131110";
var DARK_CARD = "#1C1915";
function applyDarkMode(dark) {
  // Published on T so anything reading the palette can branch on ground without
  // re-deriving it from a colour value (the rarity ramp needs exactly this).
  T.isDark  = !!dark;
  T.bg      = dark ? DARK_BG   : LIGHT_BG;
  T.card    = dark ? DARK_CARD : LIGHT_CARD;
  T.sep     = dark ? "rgba(255,255,255,0.07)" : "rgba(0,0,0,0.06)";
  T.ink     = dark ? "#EDE8E2" : "#1A1410";
  T.ink2    = dark ? "#A09080" : "#6B5C4E";
  T.ink3    = dark ? "#6B5C4E" : "#B0A396";
  T.navBg   = dark ? "rgba(19,17,16,0.88)"   : "rgba(250,247,242,0.82)";
  T.sheetBg = dark ? "#1C1915" : "#F8F6F1";
  T.inputBg = dark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.04)";
  // Translucent fills, flipped by ground (rule 3) - the iOS systemFill ladder.
  // These replace the app's old black-alpha washes, which simply vanished on a
  // dark page and left every grouped panel looking like one undifferentiated
  // sheet. fill0 is the faintest inset, fill4 the heaviest (switch-off tracks).
  T.fill0   = dark ? "rgba(255,255,255,0.035)" : "rgba(0,0,0,0.025)";
  T.fill1   = dark ? "rgba(255,255,255,0.06)"  : "rgba(0,0,0,0.04)";
  T.fill2   = dark ? "rgba(255,255,255,0.09)"  : "rgba(0,0,0,0.065)";
  T.fill3   = dark ? "rgba(255,255,255,0.13)"  : "rgba(0,0,0,0.085)";
  T.fill4   = dark ? "rgba(255,255,255,0.20)"  : "rgba(0,0,0,0.15)";
  // Hairlines, same flip. hairline is the default 1-1.5px outline; hairline2 is
  // the heavier one used where a control needs a visible resting edge.
  T.hairline  = dark ? "rgba(255,255,255,0.11)" : "rgba(0,0,0,0.08)";
  T.hairline2 = dark ? "rgba(255,255,255,0.17)" : "rgba(0,0,0,0.13)";
  // Liquid Glass tokens - adapt to light/dark so the glass effect is visible in both modes.
  // Light: use dark separators/borders (white-on-white is invisible); dark: use bright highlights.
  T.sheetGlass  = dark ? "rgba(28,25,21,0.75)"  : "rgba(255,255,255,0.78)";
  T.glassSpec   = dark ? "rgba(255,255,255,0.18)" : "rgba(0,0,0,0.07)";
  T.glassBorder = dark ? "rgba(255,255,255,0.14)" : "rgba(0,0,0,0.08)";
  T.glassLiftUp   = dark ? "0 -16px 48px rgba(0,0,0,0.55)" : "0 -12px 36px rgba(40,28,16,0.20), 0 -2px 8px rgba(40,28,16,0.10)";
  T.glassLiftDown = dark ? "0 16px 48px rgba(0,0,0,0.55)"  : "0 12px 36px rgba(40,28,16,0.18), 0 2px 8px rgba(40,28,16,0.08)";
  T.pillBg      = dark ? "rgba(22,19,17,0.76)" : "rgba(255,255,255,0.78)";
  // Card lift. On dark a drop shadow against near-black does nothing, so depth
  // is carried by a 1px top rim highlight instead - the standard iOS move.
  T.cardShadow  = dark
    ? "inset 0 1px 0 rgba(255,255,255,0.055), 0 6px 18px rgba(0,0,0,0.40)"
    : "0 1px 1px rgba(0,0,0,0.03), 0 4px 16px rgba(0,0,0,0.07)";
  // iOS 26 Liquid Glass nav bar: a far more transparent bar so content refracts
  // through it, a bright top rim + dark bottom shade for the lens curvature, an
  // overlaid specular sheen, and a clear frosted-glass capsule for the active tab
  // (the "lens" behind the selected icon) instead of a flat color fill.
  T.navGlass     = dark ? "rgba(26,23,20,0.52)"    : "rgba(255,255,255,0.50)";
  T.navRimTop    = dark ? "rgba(255,255,255,0.30)" : "rgba(255,255,255,0.90)";
  T.navRimBot    = dark ? "rgba(0,0,0,0.35)"       : "rgba(0,0,0,0.05)";
  T.navSheen     = dark ? "rgba(255,255,255,0.12)" : "rgba(255,255,255,0.65)";
  T.navPillGlass = dark ? "rgba(255,255,255,0.14)" : "rgba(255,255,255,0.62)";
  T.navPillRim   = dark ? "rgba(255,255,255,0.40)" : "rgba(255,255,255,0.95)";
  T.navPillShade = dark ? "rgba(0,0,0,0.30)"       : "rgba(0,0,0,0.07)";
  // The header shortcut bar is thick warm CREAM rather than the thin white
  // glass the bottom bar wears. It sits on the cream header, where a white
  // fill read as a foreign chip pasted on top; a deep cream reads as the same
  // material, just denser. The two values are the ones already approved on the
  // original button-bar mockup (reference/button-bar-mockup.html) - the bar's
  // #D8CBB8 cream and its near-white #FFFCF7 thumb. Went through two more
  // rounds after that: 0.88 opacity read as muddy/too dark, dialed back to
  // 0.60; then Alon asked for SOLID (no translucency at all) and lighter
  // still. Now a flat, fully opaque light cream - #EFE7D9 - a clear but
  // gentle step down from the #F7F3EE page, not a tan/beige chip. Dark keeps
  // the warmth instead of going neutral grey (the JOURNEY_DARK call) and is
  // opaque + a shade lighter than before for the same reason.
  T.creamBar     = dark ? "#483D31" : "#EFE7D9";
  T.creamBarLens = dark ? "rgba(255,247,236,0.17)" : "rgba(255,252,247,0.92)";
  // A touch more contrast than before: against a lighter, fully opaque fill
  // the same faint edge would all but disappear.
  T.creamBarEdge = dark ? "rgba(0,0,0,0.34)"       : "rgba(122,102,79,0.20)";
  // Repaint the accent/hero side of the palette, and the journey's own
  // ground, for the new mode (rule 1).
  paintPalette();
  paintJourney();
}

// Remember the last-used look across reloads so the very first paint matches
// the signed-in user's theme + mode, instead of flashing the light/purple
// default while Firestore loads. Synced to the cloud value on every change.
function lastLook() {
  try {
    return { theme: localStorage.getItem("cb_theme") || "blue", dark: localStorage.getItem("cb_dark") === "1" };
  } catch (e) { return { theme: "blue", dark: false }; }
}
function rememberLook(theme, dark) {
  try { localStorage.setItem("cb_theme", theme); localStorage.setItem("cb_dark", dark ? "1" : "0"); } catch (e) {}
  // Native shells only: keep the OS status bar legible against the new theme.
  // Defined below this point in the file, so guard for the boot-time call.
  try { if (typeof nativeStatusBar === "function") nativeStatusBar(dark); } catch (e) {}
}
(function () { var l = lastLook(); applyTheme(l.theme); applyDarkMode(l.dark); })();

// ===== NATIVE BRIDGE (Capacitor) =============================================
// Inside the iOS/Android shell, Capacitor injects window.Capacitor. Every helper
// below degrades to a no-op (or the existing web behavior) in a browser, so one
// code path serves web and native and nothing here can break the PWA.
//
// The reminder scheduling is the one that genuinely matters: on the web a note
// reminder is a setTimeout that dies the moment the tab closes (see the
// remTimers effect), so a reminder only fires if the app happens to be open.
// On native we hand the reminder to the OS, which fires it even when Richy is
// fully closed - the behavior users actually expect from a reminder.
function nativeOn() {
  try {
    return !!(window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform());
  } catch (e) { return false; }
}
function nativePlugin(name) {
  try { return (nativeOn() && window.Capacitor.Plugins && window.Capacitor.Plugins[name]) || null; }
  catch (e) { return null; }
}
// iOS notification ids must be a 32-bit signed int; note ids are Date.now()
// millisecond stamps, which overflow. Fold to a stable positive 31-bit int.
function nativeNotifId(id) {
  var s = String(id), h = 0;
  for (var i = 0; i < s.length; i++) { h = ((h << 5) - h + s.charCodeAt(i)) | 0; }
  return Math.abs(h) % 2147483647;
}
// Light tap feedback on primary controls. Silent no-op on web.
function nativeHaptic(style) {
  var H = nativePlugin("Haptics");
  if (!H) return;
  try { H.impact({ style: style || "LIGHT" }); } catch (e) {}
}
// Keep the native status bar legible against the current theme.
function nativeStatusBar(dark) {
  var S = nativePlugin("StatusBar");
  if (!S) return;
  try {
    S.setStyle({ style: dark ? "DARK" : "LIGHT" });
    if (window.Capacitor.getPlatform && window.Capacitor.getPlatform() === "android") {
      S.setBackgroundColor({ color: dark ? DARK_BG : LIGHT_BG });
    }
  } catch (e) {}
}

