// Which badges Richy can actually decide yet. A badge with no entry here is
// real, listed and drawn - it simply cannot be earned until its trigger is
// computable, which is honest in a way that quietly dropping it from the grid
// would not be. Everything below reads the context built in motivSnapshot().
var BADGE_TESTS = {
  "a-01-opening-balance":            function(c) { return c.hasOpening; },
  "a-02-first-coin":                 function(c) { return c.txCount >= 1; },
  "a-04-the-plan":                   function(c) { return c.onboarded; },
  "a-05-categorised":                function(c) { return c.catCount >= 5; },
  "a-06-filed":                      function(c) { return c.folderCount >= 1; },
  "a-07-books-open":                 function(c) { return c.cleanTotal >= 1; },
  "a-08-ledger-literate-stage-1":    function(c) { return c.txCount >= 25; },
  "a-09-hundred-coins-stage-2":      function(c) { return c.txCount >= 100; },
  "a-10-thousand-coins-stage-3":     function(c) { return c.txCount >= 1000; },
  "a-11-ten-thousand-coins":         function(c) { return c.txCount >= 10000; },

  "b-01-pay-yourself-first-stage-1": function(c) { return c.bestRate >= 10; },
  "b-02-pay-yourself-first-stage-2": function(c) { return c.bestRate >= 20; },
  "b-03-pay-yourself-first-stage-3": function(c) { return c.bestRate >= 30; },
  "b-04-half-of-it":                 function(c) { return c.bestRate >= 50; },
  "b-05-the-monk":                   function(c) { return c.bestRate >= 70; },
  "b-06-steady-hand-stage-1":        function(c) { return c.greenRun >= 3; },
  "b-07-steady-hand-stage-2":        function(c) { return c.greenRun >= 6; },
  "b-08-steady-hand-stage-3":        function(c) { return c.greenRun >= 12; },
  "b-09-the-unbroken":               function(c) { return c.greenRun >= 24; },

  "c-01-first-green":                function(c) { return c.greenTotal >= 1; },
  "c-02-two-in-a-row":               function(c) { return c.greenRun >= 2; },
  "c-03-quarter-green-stage-1":      function(c) { return c.greenRun >= 3; },
  "c-04-half-year-green-stage-2":    function(c) { return c.greenRun >= 6; },
  "c-05-full-year-green-stage-3":    function(c) { return c.greenRun >= 12; },
  "c-06-two-years-green":            function(c) { return c.greenRun >= 24; },
  "c-07-five-years-green":           function(c) { return c.greenRun >= 60; },
  "c-08-repaired":                   function(c) { return c.repaired >= 1; },

  "d-01-clean-run-stage-1":          function(c) { return c.cleanRun >= 4; },
  "d-02-clean-run-stage-2":          function(c) { return c.cleanRun >= 12; },
  "d-03-clean-run-stage-3":          function(c) { return c.cleanRun >= 26; },
  "d-04-year-of-truth":              function(c) { return c.cleanRun >= 52; },
  "d-05-shieldless":                 function(c) { return c.cleanRun >= 26 && c.shieldsSpent === 0; },

  "e-01-first-limit":                function(c) { return c.budgetCount >= 1; },
  "e-02-under-the-line-stage-1":     function(c) { return c.budgetWorst >= 1; },
  "e-03-under-the-line-stage-2":     function(c) { return c.budgetWorst >= 3; },
  "e-04-under-the-line-stage-3":     function(c) { return c.budgetWorst >= 6; },
  "e-05-the-whole-board":            function(c) { return c.budgetWorst >= 12; },
  "e-07-six-under":                  function(c) { return c.budgetOnTrack >= 6; },
  "e-08-folder-discipline":          function(c) { return c.folderCount >= 3 && c.folderRoles === c.folderCount; },

  "f-01-first-book":                 function(c) { return c.goalCount >= 1; },
  "f-02-goal-getter-stage-1":        function(c) { return c.goalsDone >= 1; },
  "f-03-goal-getter-stage-2":        function(c) { return c.goalsDone >= 3; },
  "f-04-goal-getter-stage-3":        function(c) { return c.goalsDone >= 10; },
  "f-05-twenty-books":               function(c) { return c.goalsDone >= 20; },
  "f-09-three-at-once":              function(c) { return c.goalsMoving >= 3; },

  "g-01-first-pot":                  function(c) { return c.potCount >= 1; },
  "g-02-thousand-stage-1":           function(c) { return c.savTotal >= 1000; },
  "g-03-five-figures-stage-2":       function(c) { return c.savTotal >= 10000; },
  "g-04-six-figures-stage-3":        function(c) { return c.savTotal >= 100000; },
  "g-05-seven-figures":              function(c) { return c.savTotal >= 1000000; },
  "g-06-cushion-stage-1":            function(c) { return c.cushionMonths >= 1; },
  "g-07-cushion-stage-2":            function(c) { return c.cushionMonths >= 3; },
  "g-08-cushion-stage-3":            function(c) { return c.cushionMonths >= 6; },
  "g-09-the-fortress":               function(c) { return c.cushionMonths >= 12; },

  "h-01-the-first-extra":            function(c) { return c.opening > 0 && c.netWorth > c.opening; },
  "h-02-doubled-stage-1":            function(c) { return c.opening > 0 && c.netWorth >= c.opening * 2; },
  "h-03-tripled-stage-2":            function(c) { return c.opening > 0 && c.netWorth >= c.opening * 3; },
  "h-04-fivefold-stage-3":           function(c) { return c.opening > 0 && c.netWorth >= c.opening * 5; },
  "h-05-tenfold":                    function(c) { return c.opening > 0 && c.netWorth >= c.opening * 10; },
  "h-06-hundredfold":                function(c) { return c.opening > 0 && c.netWorth >= c.opening * 100; },

  "i-01-faced-it":                   function(c) { return c.debtCount >= 1; },
  "i-04-chipped-stage-3":            function(c) { return c.debtsCleared >= 1; },
  "i-05-debt-free":                  function(c) { return c.debtCount >= 1 && c.debtsCleared === c.debtCount; },
  "i-07-snowball":                   function(c) { return c.debtsCleared >= 3; },

  "j-01-opened-the-door":            function(c) { return c.invCount >= 1; },

  "k-01-first-trip":                 function(c) { return c.tripCount >= 1; },
  "k-05-the-grand-tour":             function(c) { return c.tripsEnded >= 5; },

  "l-01-kept-track":                 function(c) { return c.noteCount >= 1; },
  "l-02-settled-up":                 function(c) { return c.notesSettled >= 1; },
  "l-03-clean-slate-stage-1":        function(c) { return c.notesSettled >= 5; },
  "l-04-clean-slate-stage-2":        function(c) { return c.notesSettled >= 25; },
  "l-05-clean-slate-stage-3":        function(c) { return c.notesSettled >= 100; },

  "n-01-open-for-business":          function(c) { return c.bizCount >= 1; },

  "o-01-two-purses":                 function(c) { return c.inHousehold; },

  "p-01-one-month-in":               function(c) { return c.daysActive >= 30; },
  "p-02-one-season":                 function(c) { return c.daysActive >= 90; },
  "p-03-half-a-year":                function(c) { return c.daysActive >= 180; },
  "p-04-one-year":                   function(c) { return c.daysActive >= 365; },
  "p-05-two-years":                  function(c) { return c.daysActive >= 730; },
  "p-06-five-years":                 function(c) { return c.daysActive >= 1825; },
  "p-07-ten-years":                  function(c) { return c.daysActive >= 3650; },

  "s-07-ten-years-green":            function(c) { return c.greenRun >= 120; }
};

// The single entry point. Everything the Profile screen renders comes out of
// this one call, so the numbers on the header, the streak card, the badge
// scroller and the activity feed can never disagree with each other.
function motivSnapshot(data) {
  var motiv = motivOf(data);
  var tx = data.tx || [];
  var today = new Date();

  var clean = cleanWeekState(motiv, today);
  var target = Number((data.onboardingData || {}).savingsTargetPct || 0);
  var green = greenMonthState(tx, motiv, target);
  var bctx = { tx: tx, categories: data.categories || [], folders: data.folders || [] };
  var bud = budgetRunState(data.budgets || [], bctx);

  // Money reads, all through the existing helpers so Profile can never disagree
  // with Overview about what the user is worth.
  var savTotal = savingsTotal(data.savings || []);
  var todayIso = isoDay(today);
  var allIncome = tx.filter(function(t) { return t.type === "income" && !isTransfer(t) && motivSettled(t, todayIso); }).reduce(function(s, t) { return s + t.amount; }, 0);
  var allExpense = tx.filter(function(t) { return t.type === "expense" && !isTransfer(t) && motivSettled(t, todayIso); }).reduce(function(s, t) { return s + t.amount; }, 0);
  var netWorth = round2(allIncome - allExpense + savTotal + businessTotal(data.businesses || []) + investingTotal(data.investing || []));
  var openingTx = tx.filter(function(t) { return isOpening(t); })[0];
  var opening = openingTx ? (openingTx.amount || 0) : 0;
  var essentials = Number((data.onboardingData || {}).monthlyEssentials || 0);
  var cushionMonths = essentials > 0 ? savTotal / essentials : 0;

  var goals = data.goals || [];
  var goalsDone = goals.filter(function(g) {
    return g.target > 0 && goalSavedAmount(g, tx, data.savings, data.businesses, data.investing) >= g.target;
  }).length;
  var goalFunded = goals.filter(function(g) {
    return goalSavedAmount(g, tx, data.savings, data.businesses, data.investing) > 0;
  }).length;

  var months = green.months;
  var bestRate = 0, repaired = 0, i;
  for (i = 0; i < months.length; i++) {
    if (months[i].rate !== null && months[i].rate > bestRate) bestRate = months[i].rate;
    // "Made it good": a red month immediately followed by a green one that beat
    // the target by at least as much as the red one missed it.
    if (i > 0 && !months[i - 1].green && months[i].green && months[i].rate !== null && months[i - 1].rate !== null) {
      if ((months[i].rate - green.target) >= (green.target - months[i - 1].rate)) repaired++;
    }
  }

  // Weeks confirmed that had no transactions at all - the design says a quiet
  // week still counts, and there is a badge that says so out loud.
  var quiet = 0;
  for (i = 0; i < motiv.weekConfirms.length; i++) {
    var wk = motiv.weekConfirms[i], wkEnd = weekAdd(wk, 1);
    var any = tx.some(function(t) { return t.date >= wk && t.date < wkEnd && !isOpening(t); });
    if (!any) quiet++;
  }

  var folders = data.folders || [];
  var notes = data.notes || [];
  var trips = data.trips || [];
  // Days since the account existed. New accounts stamp createdAt; older ones
  // fall back to their earliest transaction, which is the closest honest proxy
  // for "how long have you been doing this" that the data can supply.
  var firstDay = data.createdAt || (tx.map(function(t) { return t.date; }).sort()[0] || todayIso);
  var daysActive = Math.max(0, Math.round((parseDay(todayIso) - parseDay(firstDay)) / 86400000));
  var ctx = {
    txCount: tx.filter(function(t) { return !isOpening(t); }).length,
    hasOpening: !!openingTx,
    onboarded: data.onboardingDone === true,
    daysActive: daysActive,
    debtCount: (data.debts || []).length,
    invCount: (data.investing || []).length,
    bizCount: (data.businesses || []).length,
    tripCount: trips.length,
    tripsEnded: trips.filter(function(t) { return t.ended; }).length,
    noteCount: notes.length,
    notesSettled: notes.filter(function(n) { return n && n.settled; }).length,
    inHousehold: !!data.householdId,
    shieldsSpent: clean.shielded.length,
    catCount: (data.categories || []).length,
    budgetCount: (data.budgets || []).length,
    budgetOnTrack: bud.onTrack,
    budgetBest: bud.best,
    budgetWorst: bud.runs.length === (data.budgets || []).length && bud.runs.length ? bud.runs[bud.runs.length - 1].run : 0,
    folderCount: folders.length,
    folderRoles: folders.filter(function(f) { return !!folderRole(f); }).length,
    goalCount: goals.length, goalsDone: goalsDone, goalFunded: goalFunded,
    goalsMoving: goalFunded, goalsEarly: 0, goalLongest: 0,
    potCount: (data.savings || []).length, potNoDipMonths: 0,
    savTotal: savTotal, netWorth: netWorth, opening: opening, cushionMonths: cushionMonths,
    debtsCleared: (data.debts || []).filter(function(d) { return d && d.cleared; }).length,
    cleanRun: clean.run, cleanTotal: clean.total, shieldsEarned: clean.shields, quietWeeks: quiet,
    greenRun: green.run, greenTotal: green.total, bestRate: bestRate, repaired: repaired
  };

  // Which badges are currently satisfied. A badge, once earned, is kept forever
  // even if the condition later stops holding - rule 1: XP never decreases.
  var held = {}, sharedOn = {};
  for (i = 0; i < motiv.badges.length; i++) { held[motiv.badges[i].id] = motiv.badges[i]; sharedOn[motiv.badges[i].id] = !!motiv.badges[i].shared; }
  var earned = [], newly = [], badgeXp = 0;
  for (i = 0; i < BADGES.length; i++) {
    var b = BADGES[i];
    var rec = held[b.id];
    // A badge with no entry in BADGE_TESTS cannot be decided yet. It still
    // appears in the collection, drawn and named - it simply never grants.
    var t = BADGE_TESTS[b.id];
    var on = rec || (t ? t(ctx) : false);
    if (!on) continue;
    badgeXp += MOTIV.rarityXp[b.r] || 0;
    var row = { def: b, at: rec ? rec.at : isoDay(today), early: rec ? !!rec.early : false, shared: !!sharedOn[b.id] };
    earned.push(row);
    if (!rec) newly.push(row);
  }

  // XP. Behaviour first, then badges. Nothing here can go negative.
  var xp = clean.total * MOTIV.xp.cleanWeek
         + green.total * MOTIV.xp.greenMonth
         + Math.min(bud.onTrack * MOTIV.xp.budgetHeld, MOTIV.xp.budgetHeldCap)
         + goalsDone * MOTIV.xp.goalDone
         + badgeXp;
  var level = levelFor(xp);
  var cur = xpForLevel(level), next = level >= MOTIV.maxLevel ? cur : xpForLevel(level + 1);
  var pct = next > cur ? Math.round(((xp - cur) / (next - cur)) * 100) : 100;

  return {
    motiv: motiv, ctx: ctx, clean: clean, green: green, budgets: bud,
    xp: xp, level: level, pctToNext: Math.max(0, Math.min(100, pct)),
    xpToNext: Math.max(0, next - xp), rank: rankFor(level, ctx),
    badges: earned, newBadges: newly, badgeTotal: BADGES.length,
    hiddenOnShare: earned.filter(function(e) { return e.def.reveals === "wealth" && !e.shared; }).length
  };
}

// Cloud backend: Firebase Auth owns identity + sessions (sign-up, sign-in,
// password, email), and Cloud Firestore stores one document per user
// (collection "users", keyed by the Firebase uid) holding their whole data blob.
//
// Firestore's security rules authorize on request.auth, which Firebase Auth
// populates directly - so the client signs in and the rules just work, with no
// bridge or token exchange in between.
//
// Config: Firebase's web config lives in firebase-init.js, loaded by the page
// shell before this app runs. cloudReady()/cloudConfigured() guard every call
// so the app can still boot and explain itself before setup is done.
//
// (An earlier build put Clerk in front of this and bridged Clerk sessions into
// Firebase custom tokens. That whole implementation is preserved as the
// `clerk-auth-integration` skill in .claude/skills/ if it is ever wanted back.)
function _fb() {
  return (typeof window !== "undefined" && window.firebase) ? window.firebase : null;
}
function cloudReady() {
  var f = _fb();
  return !!(f && f.apps && f.apps.length);
}
// True once real keys are in firebase-init.js, regardless of whether the SDK
// scripts actually loaded - lets cloudErrorMsg() tell "never configured" apart
// from "SDK failed to load this time" (ad blocker, flaky connection).
function cloudConfigured() {
  return typeof window !== "undefined" && window.__RICHY_FB_CONFIGURED__ === true;
}
function cloudErrorMsg() {
  return cloudConfigured() ? CLOUD_CONNECT_MSG : CLOUD_SETUP_MSG;
}
function _auth() { return _fb().auth(); }
function _fsdb() { return _fb().firestore(); }

var CLOUD = {
  // Subscribe to sign-in state. cb receives the Firebase user (or null).
  // Returns an unsubscribe function. Fires once immediately with the restored
  // session.
  onAuth: function(cb) {
    if (!cloudReady()) { cb(null); return function () {}; }
    return _auth().onAuthStateChanged(cb);
  },
  signUp: function(email, password) {
    return _auth().createUserWithEmailAndPassword(email, password);
  },
  signIn: function(email, password) {
    return _auth().signInWithEmailAndPassword(email, password);
  },
  signInGoogle: function() {
    var provider = new (_fb().auth.GoogleAuthProvider)();
    return _auth().signInWithPopup(provider);
  },
  signOut: function() {
    return cloudReady() ? _auth().signOut() : Promise.resolve();
  },
  // A fresh Firebase ID token, used to authenticate the user's own calls to our
  // API functions (the server verifies it and derives uid itself - the client
  // never gets to assert its own uid to those endpoints).
  getIdToken: function() {
    var cu = cloudReady() ? _auth().currentUser : null;
    return cu ? cu.getIdToken() : Promise.resolve(null);
  },
  loadUser: function(uid) {
    return _fsdb().collection("users").doc(uid).get().then(function (snap) {
      return snap.exists ? snap.data() : null;
    });
  },
  saveUser: function(uid, data) {
    if (!cloudReady() || !uid) return Promise.resolve();
    // Firestore v8 throws SYNCHRONOUSLY on any undefined field value, before a
    // promise even exists - so a single stray `undefined` (e.g. a merge that
    // drops a key) can silently kill saving instead of raising the normal
    // error banner. Stripping undefined here means no field can ever do that.
    return _fsdb().collection("users").doc(uid).set(JSON.parse(JSON.stringify(data)));
  },
  // ---- Bank Sync (Apple Pay / Google Pay via phone automations) ----------------
  // syncKeys/{sha256(key)} maps a per-user random token to their uid so
  // api/bank-sync.js can resolve who a POSTed transaction belongs to (only the
  // hash is stored - the raw key is never in the database). The inbox
  // subcollection is server-written only; the running app drains it into real
  // transactions. `key` here is already the hash.
  createSyncKey: function(key, uid) {
    if (!cloudReady() || !uid) return Promise.resolve();
    return _fsdb().collection("syncKeys").doc(key).set({ uid: uid, createdAt: Date.now() });
  },
  deleteSyncKey: function(key) {
    if (!cloudReady()) return Promise.resolve();
    return _fsdb().collection("syncKeys").doc(key).delete();
  },
  subscribeSyncInbox: function(uid, cb) {
    if (!cloudReady() || !uid) return function() {};
    return _fsdb().collection("users").doc(uid).collection("syncInbox").onSnapshot(
      function(qs) {
        var out = [];
        qs.forEach(function(d) { out.push(Object.assign({ _id: d.id }, d.data())); });
        cb(out);
      },
      function() {}
    );
  },
  deleteSyncInboxDocs: function(uid, ids) {
    if (!cloudReady() || !uid || !ids.length) return Promise.resolve();
    var batch = _fsdb().batch();
    ids.forEach(function(id) { batch.delete(_fsdb().collection("users").doc(uid).collection("syncInbox").doc(id)); });
    return batch.commit();
  },

  hasPasswordProvider: function() {
    var cu = cloudReady() ? _auth().currentUser : null;
    if (!cu) return false;
    var pd = cu.providerData || [];
    for (var i = 0; i < pd.length; i++) {
      if (pd[i].providerId === "password") return true;
    }
    return false;
  },
  // Firebase requires a recent sign-in before changing a password or email, so
  // callers reauthenticate() first and then call the setter.
  reauthenticate: function(email, oldPw) {
    var cu = _auth().currentUser;
    var cred = _fb().auth.EmailAuthProvider.credential(email, oldPw);
    return cu.reauthenticateWithCredential(cred);
  },
  updatePassword: function(newPw) {
    return _auth().currentUser.updatePassword(newPw);
  },
  linkPassword: function(email, pw) {
    var cu = _auth().currentUser;
    var cred = _fb().auth.EmailAuthProvider.credential(email, pw);
    return cu.linkWithCredential(cred);
  },
  sendPasswordReset: function(email) {
    return _auth().sendPasswordResetEmail(email);
  },
  updateEmail: function(newEmail) {
    return _auth().currentUser.updateEmail(newEmail);
  },

  // ---- Households (Collab / couples mode) ------------------------------------
  // A household is a shared document at households/{hid}. SHARED data (budgets,
  // goals, categories, shared transactions) lives here; PRIVATE transactions and
  // personal settings stay in each member's users/{uid} doc and never enter here.
  // Membership is enforced by Firestore rules: only listed memberUids (or an
  // invited email in pendingEmails, who can accept) may touch the doc.
  createHousehold: function(member, name) {
    var ref = _fsdb().collection("households").doc();
    var data = {
      name: name || "Our Household",
      createdBy: member.uid,
      memberUids: [member.uid],
      members: [{ uid: member.uid, name: member.name || "", email: (member.email || "").toLowerCase() }],
      pendingEmails: [],
      createdAt: Date.now()
    };
    return ref.set(data).then(function() { return ref.id; });
  },
  loadHousehold: function(hid) {
    return _fsdb().collection("households").doc(hid).get().then(function(snap) {
      return snap.exists ? Object.assign({ id: snap.id }, snap.data()) : null;
    });
  },
  // Live updates so a partner's membership/invite changes appear without reload.
  subscribeHousehold: function(hid, cb) {
    if (!cloudReady() || !hid) { cb(null); return function() {}; }
    return _fsdb().collection("households").doc(hid).onSnapshot(
      function(snap) { cb(snap.exists ? Object.assign({ id: snap.id }, snap.data()) : null); },
      function() { cb(null); }
    );
  },
  // Find households this email has been invited to but not yet joined. The query
  // is constrained to pendingEmails array-contains email so every match satisfies
  // the read rule.
  findInvites: function(email) {
    if (!cloudReady() || !email) return Promise.resolve([]);
    return _fsdb().collection("households").where("pendingEmails", "array-contains", email.toLowerCase()).get()
      .then(function(qs) {
        var out = [];
        qs.forEach(function(d) { out.push(Object.assign({ id: d.id }, d.data())); });
        return out;
      });
  },
  inviteToHousehold: function(hid, email) {
    var FV = _fb().firestore.FieldValue;
    return _fsdb().collection("households").doc(hid).update({
      pendingEmails: FV.arrayUnion((email || "").toLowerCase())
    });
  },
  cancelInvite: function(hid, email) {
    var FV = _fb().firestore.FieldValue;
    return _fsdb().collection("households").doc(hid).update({
      pendingEmails: FV.arrayRemove((email || "").toLowerCase())
    });
  },
  acceptInvite: function(hid, member) {
    var FV = _fb().firestore.FieldValue;
    return _fsdb().collection("households").doc(hid).update({
      memberUids: FV.arrayUnion(member.uid),
      members: FV.arrayUnion({ uid: member.uid, name: member.name || "", email: (member.email || "").toLowerCase() }),
      pendingEmails: FV.arrayRemove((member.email || "").toLowerCase())
    });
  },
  leaveHousehold: function(hid, member) {
    var FV = _fb().firestore.FieldValue;
    return _fsdb().collection("households").doc(hid).update({
      memberUids: FV.arrayRemove(member.uid),
      members: FV.arrayRemove({ uid: member.uid, name: member.name || "", email: (member.email || "").toLowerCase() })
    });
  },
  saveHousehold: function(hid, data) {
    if (!cloudReady() || !hid) return Promise.resolve();
    return _fsdb().collection("households").doc(hid).set(data, { merge: true });
  },

  // ── The social graph ──────────────────────────────────────────────────────
  // Following is not household membership and shares nothing financial. See
  // firestore.rules for why identity (profiles) and progress (profileStats)
  // are two documents: anyone signed in can find you by handle, but only an
  // approved follower can read your level, streaks or badges. No amount is
  // ever written to either one.
  publishProfile: function(uid, card, stats) {
    if (!cloudReady() || !uid) return Promise.resolve();
    var db = _fsdb();
    return Promise.all([
      db.collection("profiles").doc(uid).set(card, { merge: true }),
      db.collection("profileStats").doc(uid).set(stats, { merge: true })
    ]);
  },
  // Handles are create-only in the rules, so a claim fails loudly if taken
  // rather than silently stealing someone's name.
  claimHandle: function(handle, uid) {
    if (!cloudReady()) return Promise.reject(new Error("offline"));
    return _fsdb().collection("handles").doc(handle).get().then(function(d) {
      if (d.exists) {
        if (d.data().uid === uid) return handle;      // already yours - no-op
        throw new Error("taken");
      }
      return _fsdb().collection("handles").doc(handle).set({ uid: uid }).then(function() { return handle; });
    });
  },
  findByHandle: function(handle) {
    if (!cloudReady() || !handle) return Promise.resolve(null);
    return _fsdb().collection("handles").doc(handle).get().then(function(d) {
      if (!d.exists) return null;
      return CLOUD.loadProfile(d.data().uid);
    });
  },
  loadProfile: function(uid) {
    if (!cloudReady() || !uid) return Promise.resolve(null);
    return _fsdb().collection("profiles").doc(uid).get().then(function(d) {
      return d.exists ? Object.assign({ uid: uid }, d.data()) : null;
    });
  },
  // Only ever succeeds for someone who has approved you - the rules enforce it,
  // this just surfaces the refusal as null instead of an exception.
  loadProfileStats: function(uid) {
    if (!cloudReady() || !uid) return Promise.resolve(null);
    return _fsdb().collection("profileStats").doc(uid).get()
      .then(function(d) { return d.exists ? d.data() : null; })
      .catch(function() { return null; });
  },
  sendFollowRequest: function(from, to, card) {
    if (!cloudReady() || !from || !to || from === to) return Promise.resolve();
    return _fsdb().collection("followRequests").doc(from + "__" + to).set({
      from: from, to: to,
      handle: (card && card.handle) || "", name: (card && card.name) || "",
      at: new Date().toISOString()
    });
  },
  incomingRequests: function(uid) {
    if (!cloudReady() || !uid) return Promise.resolve([]);
    return _fsdb().collection("followRequests").where("to", "==", uid).get().then(function(s) {
      return s.docs.map(function(d) { return Object.assign({ id: d.id }, d.data()); });
    }).catch(function() { return []; });
  },
  // Approval. The edge is created by the TARGET - a follower cannot grant
  // themselves access - and the request is cleared once the edge exists.
  acceptRequest: function(followerUid, myUid) {
    if (!cloudReady()) return Promise.resolve();
    var db = _fsdb();
    return db.collection("follows").doc(followerUid + "__" + myUid).set({
      follower: followerUid, target: myUid, at: new Date().toISOString()
    }).then(function() {
      return db.collection("followRequests").doc(followerUid + "__" + myUid).delete();
    });
  },
  declineRequest: function(followerUid, myUid) {
    if (!cloudReady()) return Promise.resolve();
    return _fsdb().collection("followRequests").doc(followerUid + "__" + myUid).delete();
  },
  // Both directions, and both revocable: unfollow someone, or remove a follower.
  listFollowing: function(uid) {
    if (!cloudReady() || !uid) return Promise.resolve([]);
    return _fsdb().collection("follows").where("follower", "==", uid).get().then(function(s) {
      return s.docs.map(function(d) { return d.data().target; });
    }).catch(function() { return []; });
  },
  listFollowers: function(uid) {
    if (!cloudReady() || !uid) return Promise.resolve([]);
    return _fsdb().collection("follows").where("target", "==", uid).get().then(function(s) {
      return s.docs.map(function(d) { return d.data().follower; });
    }).catch(function() { return []; });
  },
  removeFollow: function(followerUid, targetUid) {
    if (!cloudReady()) return Promise.resolve();
    return _fsdb().collection("follows").doc(followerUid + "__" + targetUid).delete();
  }
};

// Catches any render error anywhere in the tree so one bad state can never
// blank the whole app - shows a friendly reload screen instead. Wired around
// <App/> by both the production shell (index.html) and the dev harness
// (preview.html); the user's data is safe because everything lives in Firestore.
class ErrorBoundary extends React.Component {
  constructor(props) { super(props); this.state = { err: null }; }
  static getDerivedStateFromError(err) { return { err: err }; }
  componentDidCatch(err, info) {
    try { console.error("Richy crashed:", err, info && info.componentStack); } catch (e) {}
  }
  render() {
    if (!this.state.err) return this.props.children;
    var dark = false;
    try { dark = localStorage.getItem("cb_dark") === "1"; } catch (e) {}
    var bg = dark ? "#131110" : "#F7F3EE", ink = dark ? "#F2EDE6" : "#1A1410", sub = dark ? "#B0A396" : "#6E6259";
    return React.createElement("div", { style: { position: "fixed", inset: 0, background: bg, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: UI, padding: 24, zIndex: 9999 } },
      React.createElement("div", { style: { textAlign: "center", maxWidth: 340 } },
        React.createElement("div", { style: { width: 56, height: 56, borderRadius: 18, background: "#0D0C18", margin: "0 auto 16px", display: "flex", alignItems: "center", justifyContent: "center" } },
          React.createElement("span", { style: { fontFamily: UI, fontSize: 34, fontWeight: MARK_WEIGHT, color: "#C8973A", lineHeight: 1 } }, "R")),
        React.createElement("div", { style: { fontSize: 19, fontWeight: DISP_WEIGHT, fontFamily: DISP, color: ink, marginBottom: 8 } }, "Something went wrong"),
        React.createElement("div", { style: { fontSize: 13.5, color: sub, lineHeight: 1.5, marginBottom: 18 } }, "Your data is safe in the cloud. Reload the app to pick up right where you left off."),
        React.createElement("button", { onClick: function () { location.reload(); }, style: { border: "none", cursor: "pointer", background: "#C8973A", color: "#fff", fontSize: 14.5, fontWeight: 700, padding: "12px 28px", borderRadius: 12, fontFamily: UI } }, "Reload Richy")
      )
    );
  }
}

function Card(props) {
  return (
    // The two motion flags are forwarded because the reduced-motion media query
    // keys off them - a Card that swallowed the attribute would keep animating
    // for a reader who asked the OS for stillness.
    <div data-biz-motion={props["data-biz-motion"]} data-invest-motion={props["data-invest-motion"]}
      style={Object.assign({
      background: props.glass ? T.sheetGlass : T.card,
      borderRadius: 20,
      border: props.glass ? "1px solid " + T.glassBorder : "none",
      boxShadow: props.glass
        ? "0 4px 24px rgba(0,0,0,0.09), inset 0 1px 0 " + T.glassSpec
        : T.cardShadow,
      backdropFilter: props.glass ? "blur(28px) saturate(180%)" : "none",
      WebkitBackdropFilter: props.glass ? "blur(28px) saturate(180%)" : "none",
    }, props.style)}>
      {props.children}
    </div>
  );
}

function RichyLogo(props) {
  var size = props.size || 40;
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg" style={props.style || {}}>
      <rect width="100" height="100" rx={22} fill="#0D0C18" />
      <text x="50" y="75" textAnchor="middle" fontFamily={UI} fontSize="72" fontWeight={MARK_WEIGHT} fill="#C8973A">R</text>
    </svg>
  );
}

// Fluid animated gradient circle - stands in for the plain close-chat X on the
// Advisor screen. CSS-only (conic gradients spinning via a Houdini-registered
// custom property) so it costs nothing next to the GPU orb Richard uses
// elsewhere; browsers without @property support just render it static.
function ensureSiriOrbCss() {
  var id = "richy-siri-orb-css";
  if (document.getElementById(id)) return;
  var st = document.createElement("style"); st.id = id;
  st.textContent = [
    "@property --sorb-angle{syntax:'<angle>';inherits:false;initial-value:0deg;}",
    // A translucent backing fill sits under the swirl so the gaps between the
    // conic-gradient arcs read as soft glass rather than a hole straight
    // through to whatever's behind the orb in the DOM (the ribbon shader
    // canvas, in the voice overlay) - a light tint, not a solid disc.
    ".rc-siri-orb{display:grid;grid-template-areas:'stack';overflow:hidden;border-radius:50%;position:relative;background:radial-gradient(circle,rgba(0,0,0,0.1) 0%,rgba(0,0,0,0.04) 40%,transparent 72%),var(--sorb-base);}",
    // Every layer turns at ONE rate, in ONE direction, separated by fixed
    // offsets - the source component's mixed multipliers (1.2 / 0.8 / -1.5 /
    // 2.1 / -0.7) made the layers beat against each other, which is what read
    // as the colors twitching rather than turning. Wide arcs (color across
    // ~240deg instead of ~90deg) keep the body solid instead of gauzy.
    ".rc-siri-orb::before{content:'';display:block;grid-area:stack;width:100%;height:100%;border-radius:50%;background:"
      + "conic-gradient(from calc(var(--sorb-angle,0deg) + 0deg) at 32% 62%,var(--sorb-c3) 0deg,transparent 130deg 230deg,var(--sorb-c3) 360deg),"
      + "conic-gradient(from calc(var(--sorb-angle,0deg) + 72deg) at 68% 38%,var(--sorb-c2) 0deg,transparent 140deg 220deg,var(--sorb-c2) 360deg),"
      + "conic-gradient(from calc(var(--sorb-angle,0deg) + 144deg) at 62% 72%,var(--sorb-c1) 0deg,transparent 135deg 225deg,var(--sorb-c1) 360deg),"
      + "conic-gradient(from calc(var(--sorb-angle,0deg) + 216deg) at 28% 30%,var(--sorb-c2) 0deg,transparent 145deg 215deg,var(--sorb-c2) 360deg),"
      + "conic-gradient(from calc(var(--sorb-angle,0deg) + 288deg) at 74% 74%,var(--sorb-c1) 0deg,transparent 130deg 230deg,var(--sorb-c1) 360deg),"
      + "radial-gradient(ellipse 130% 95% at 42% 58%,var(--sorb-c3) 0%,var(--sorb-c1) 45%,transparent 78%);"
      + "filter:blur(var(--sorb-blur,8px)) contrast(var(--sorb-contrast,1.8)) saturate(var(--sorb-sat,1.35));animation:rcSorbSpin var(--sorb-dur,20s) linear infinite;transform:translateZ(0);will-change:transform;}",
    ".rc-siri-orb::after{content:'';display:block;grid-area:stack;width:100%;height:100%;border-radius:50%;background:radial-gradient(circle at 45% 55%,rgba(255,255,255,0.1) 0%,rgba(255,255,255,0.05) 30%,transparent 60%);mix-blend-mode:overlay;}",
    "@keyframes rcSorbSpin{from{--sorb-angle:0deg;}to{--sorb-angle:360deg;}}",
    "@media (prefers-reduced-motion:reduce){.rc-siri-orb::before{animation:none;}}"
  ].join("");
  document.head.appendChild(st);
}
// Lift a theme hex toward white. The orb needs a light tone in the mix or a
// single-hue theme (blue, purple) collapses into one flat ball and the swirl
// stops reading. jrHex is defined next to jrRgba above.
function sorbLift(hex, f) {
  var c = jrHex(hex);
  return "rgb(" + Math.round((c[0] + (1 - c[0]) * f) * 255)
    + "," + Math.round((c[1] + (1 - c[1]) * f) * 255)
    + "," + Math.round((c[2] + (1 - c[2]) * f) * 255) + ")";
}
function SiriOrb(props) {
  ensureSiriOrbCss();
  var size = props.size || 48;
  var blur = Math.max(size * 0.08, 3.5);
  var contrast = Math.max(size * 0.003, 1.8);
  // Colors ride the live theme - the accent pair plus the deeper trend tone,
  // all from one family. Brand gold is deliberately NOT in here: against the
  // blue and purple themes it reads as a yellow blob rather than a highlight.
  return (
    <div className="rc-siri-orb" aria-hidden="true" style={{
      width: size, height: size, flexShrink: 0,
      "--sorb-c1": props.c1 || sorbLift(T.orange, 0.22),
      "--sorb-c2": props.c2 || sorbLift(T.orangeHi, 0.5),
      "--sorb-c3": props.c3 || sorbLift(T.trendLineA || T.orange, 0.34),
      "--sorb-dur": (props.duration || 20) + "s",
      "--sorb-blur": blur + "px",
      "--sorb-contrast": contrast,
      "--sorb-sat": props.sat || 1.35,
      "--sorb-base": props.base || jrRgba(T.orange, 0.72)
    }} />
  );
}

// === LOADING & THINKING ANIMATIONS ===
// Perceived-performance toolkit. Every AI wait in the app funnels through these
// pieces so waiting reads as Richard visibly working, not a stalled screen:
// typing dots, a rotating "what I'm doing right now" phrase, and a staged
// checklist with a progress bar that always moves forward, never runs backwards,
// and only finishes when the real work returns.
function ensureLoadingCss() {
  var id = "richy-loading-css";
  if (document.getElementById(id)) return;
  var st = document.createElement("style"); st.id = id;
  st.textContent = [
    "@keyframes rclDot{0%,60%,100%{transform:translateY(0);opacity:0.35}30%{transform:translateY(-4px);opacity:1}}",
    "@keyframes rclPhrase{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}",
    "@keyframes rclBreathe{0%,100%{transform:scale(1)}50%{transform:scale(1.055)}}",
    "@keyframes rclGlow{0%,100%{opacity:0.45;transform:scale(0.92)}50%{opacity:0.95;transform:scale(1.18)}}",
    "@keyframes rclSheen{from{transform:translateX(-130%)}to{transform:translateX(430%)}}",
    "@keyframes rclPing{from{opacity:0.55;transform:scale(0.6)}to{opacity:0;transform:scale(2.1)}}",
    "@keyframes rclPop{0%{transform:scale(0.5)}60%{transform:scale(1.18)}100%{transform:scale(1)}}",
    "@keyframes rclFadeSeg{from{opacity:0}to{opacity:1}}",
    ".rcl-seg{display:inline-block;opacity:0;animation-name:rclFadeSeg;animation-timing-function:ease-out;animation-fill-mode:forwards;}",
    ".rcl-seg-space{white-space:pre;}",
    "@media (prefers-reduced-motion:reduce){*{animation-duration:0.001s!important;animation-iteration-count:1!important;transition-duration:0.001s!important}}",
  ].join("");
  document.head.appendChild(st);
}

// === MOTION SYSTEM ===
// One vocabulary for everything that moves, from the "Richy Motion" design pass.
// Two ideas hold it together:
//
//   1. Durations and curves are CSS custom properties, never literals. A single
//      --m-scale retimes the whole app, and prefers-reduced-motion collapses it
//      to nothing without every call site having to check.
//   2. Motion only ever does one of three jobs - content arriving (rcRise),
