    var k = e.key;
    var v = null;
    if (k === "ArrowRight" || k === "ArrowUp") v = value + step;
    else if (k === "ArrowLeft" || k === "ArrowDown") v = value - step;
    else if (k === "PageUp") v = value + step * 10;
    else if (k === "PageDown") v = value - step * 10;
    else if (k === "Home") v = 0;
    else if (k === "End") v = max;
