          {(props.businesses || []).map(function(b) { return <option key={"business:" + b.id} value={"business:" + b.id}>{b.name}</option>; })}
          {(props.investing || []).map(function(v) { return <option key={"investing:" + v.id} value={"investing:" + v.id}>{v.name}</option>; })}
